// The design fixtures (app/design/data/fixtures, real crawls: see its README), loaded lazily and brought up to the
// current contract. They're git-ignored and regenerated by `node app/design/data/extract/run-all.mjs`; when they're
// missing, every mock answer says so in plain words. This module is only ever imported with VITE_TRANSPORT=mock,
// so none of it reaches a real build.
import type { GridPage, UrlRow } from '../grids';
import type { Analysis, Checks, CrawlListItem, CrawlStats, ProgressEvent } from '../types';

const files = import.meta.glob<unknown>('/design/data/fixtures/**/*.json', { import: 'default' });

export type FixtureCrawl = 'garden' | 'synthetic';

export class MissingFixtureError extends Error {
  constructor(path: string) {
    super(`Missing fixture: ${path}`);
  }
}

export function hasFixtures(): boolean {
  return Object.keys(files).length > 0;
}

export async function fixture<T>(path: string): Promise<T> {
  const load = files[`/design/data/fixtures/${path}`];
  if (!load) throw new MissingFixtureError(path);
  return (await load()) as T;
}

export async function optionalFixture<T>(path: string): Promise<T | null> {
  return files[`/design/data/fixtures/${path}`] ? fixture<T>(path) : null;
}

// The fixtures were saved from the sidecar at e5223b6. These bring them up to the contract as it is now.

export function adaptCrawlItem(raw: Record<string, unknown>): CrawlListItem {
  const { urlCount, ...rest } = raw;
  return {
    ...(rest as unknown as CrawlListItem),
    fetchedUrlCount:
      typeof raw.fetchedUrlCount === 'number' ? raw.fetchedUrlCount : typeof urlCount === 'number' ? urlCount : 0,
    error: typeof raw.error === 'string' ? raw.error : null,
  };
}

export function adaptAnalysis(raw: Record<string, unknown>): Analysis {
  return {
    ...(raw as unknown as Analysis),
    outOfDate: typeof raw.outOfDate === 'boolean' ? raw.outOfDate : false,
    outOfDateReasons: Array.isArray(raw.outOfDateReasons) ? (raw.outOfDateReasons as Analysis['outOfDateReasons']) : [],
  };
}

export function adaptStats(raw: Record<string, unknown>): CrawlStats {
  return {
    ...(raw as unknown as CrawlStats),
    notCheckedCount: typeof raw.notCheckedCount === 'number' ? raw.notCheckedCount : 0,
  };
}

export type LiveSnapshot = Omit<ProgressEvent, 'crawlId' | 'status'> & { pages: number };

export function adaptSnapshot(raw: Record<string, unknown>): LiveSnapshot {
  const rate =
    typeof raw.urlsPerSecond === 'number'
      ? raw.urlsPerSecond
      : typeof raw.pagesPerSecond === 'number'
        ? raw.pagesPerSecond
        : 0;
  const number = (key: string) => (typeof raw[key] === 'number' ? raw[key] : 0);
  return {
    elapsedMs: number('elapsedMs'),
    discovered: number('discovered'),
    queued: number('queued'),
    inFlight: number('inFlight'),
    fetched: number('fetched'),
    htmlPages: number('htmlPages'),
    redirects: number('redirects'),
    errors: number('errors'),
    blocked: number('blocked'),
    robotsDisallowed: number('robotsDisallowed'),
    skipped: number('skipped'),
    bytesDownloaded: number('bytesDownloaded'),
    urlsPerSecond: rate,
    pages: number('pages'),
  };
}

/** The fixtures' content types as E3a's `type` column names them. */
const TYPES: Record<string, string> = {
  html: 'page',
  image: 'image',
  javascript: 'script',
  css: 'stylesheet',
  font: 'font',
  video: 'media',
  audio: 'media',
  pdf: 'pdf',
};

/**
 * A row of the design fixtures' urls.json under E3a's column names. Every fixture row was fetched; the analysis's
 * columns (issues by severity) come from the row's own list of checks and the catalog's severities.
 */
export function adaptUrlRow(raw: Record<string, unknown>, severities: ReadonlyMap<string, string>): Required<UrlRow> {
  // The fixtures are the engine's own output: each field is taken as the row's type says.
  const value = (key: string) => (raw[key] ?? null) as never;
  const checks = Array.isArray(raw.issues) ? raw.issues.filter((id): id is string => typeof id === 'string') : [];
  const count = (severity: string) => checks.filter((id) => severities.get(id) === severity).length;
  const type = typeof raw.type === 'string' ? raw.type : null;
  return {
    id: typeof raw.id === 'number' ? raw.id : 0,
    url: typeof raw.url === 'string' ? raw.url : '',
    fetched: true,
    isInternal: value('isInternal'),
    source: value('source'),
    depth: value('depth'),
    type: type === null ? null : (TYPES[type] ?? 'other'),
    statusCode: value('statusCode'),
    statusClass: value('statusClass'),
    outcome: value('outcome'),
    redirectTarget: value('redirectUrl'),
    redirectTargetStatusCode: null,
    indexable: value('indexable'),
    indexability: value('indexabilityReason'),
    noindex: value('isNoindex'),
    nofollow: value('isNofollow'),
    canonicalUrl: value('canonicalUrl'),
    contentType: value('contentType'),
    title: value('title'),
    description: value('metaDescription'),
    h1: value('h1'),
    h1Count: value('h1Count'),
    wordCount: value('wordCount'),
    outlinks: value('outlinks'),
    sizeBytes: value('sizeBytes'),
    responseMs: value('responseMs'),
    ttfbMs: value('ttfbMs'),
    titleLength: value('titleLength'),
    descriptionLength: value('metaDescriptionLength'),
    finalUrl: (raw.finalUrl ?? raw.url ?? null) as never,
    finalStatusCode: (raw.finalStatusCode ?? raw.statusCode ?? null) as never,
    inSitemap: value('inSitemap'),
    inlinks: value('inlinks'),
    issues: checks.length,
    errors: count('error'),
    warnings: count('warning'),
    notices: count('notice'),
  };
}

export async function urlRows(crawl: FixtureCrawl): Promise<Required<UrlRow>[]> {
  const [file, catalog] = await Promise.all([
    fixture<{ rows: Record<string, unknown>[] }>(
      crawl === 'garden' ? 'garden/urls.json' : 'synthetic/urls-sample.json',
    ),
    fixture<Checks>('api/checks.json'),
  ]);
  const severities = new Map(catalog.checks.map((check) => [check.id, check.severity]));
  return file.rows.map((row) => adaptUrlRow(row, severities));
}

export type { GridPage };
